SmScpuExecResult sm_scpu_page_0080E2(SmScpuState *cpu, const SmScpuBus *bus) {
    size_t lo=0u, hi=103u;
    const uint32_t key=sm_scpu_context_key(cpu);
    while (lo < hi) {
        const size_t mid=lo+(hi-lo)/2u;
        const SmSharedRecord *r=&records_0080E2[mid];
        if (key < r->key) hi=mid;
        else if (key > r->key) lo=mid+1u;
        else return sm_v18_shared_execute(cpu,bus,r->body,parameters_0080E2+r->offset);
    }
    return SM_SCPU_NOT_MINE;
}

